import glob, xml.etree.ElementTree as ET
# supplier / customer names
for f in sorted(glob.glob("*/*.xml")):
    root=ET.parse(f).getroot()
    emit=root.find('.//{*}emit/{*}xNome'); dest=root.find('.//{*}dest/{*}xNome')
    xE=emit.text if emit is not None else None
    xD=dest.text if dest is not None else None
    print(f.split('/')[-1], "| emit:", xE, "| dest:", xD)
# full arithmetic check vs apuracao table
vals={2301:18000,2302:24000,2303:9500,2304:31000,2305:4200,2306:42000,2307:56000,
      2308:12500,2309:38000,2310:7800,2311:61000,2312:176000}
xmlv={}
for f in glob.glob("saidas/*.xml"):
    nNF=None;vNF=None
    root=ET.parse(f).getroot()
    for e in root.iter():
        t=e.tag.split('}')[-1]
        if t=='nNF': nNF=int(e.text)
        if t=='vNF': vNF=float(e.text)
    xmlv[nNF]=vNF
assert vals==xmlv, (vals,xmlv)
tot=sum(vals.values())
print("soma saidas:",tot,"| x0.9%",round(tot*0.009,2),"| x0.1%",round(tot*0.001,2))
for n,v in vals.items(): print(n, v, round(v*0.009,2), round(v*0.001,2))
ent={2314:62000,2316:40000,2317:60000}
cbs=sum(round(v*0.009,2) for v in ent.values()); ibs=sum(round(v*0.001,2) for v in ent.values())
print("creditos:",cbs,ibs,"| saldos:",round(tot*0.009,2)-cbs,round(tot*0.001,2)-ibs)
print("PIS 480000*0.0065 =",480000*0.0065,"| COFINS 480000*0.03 =",480000*0.03)
EOF

